package accesslog

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
	"time"
)

const maxLineLen = 4096 // これより長い行は壊れた行として扱う

// Entry はアクセスログの1行。
type Entry struct {
	Time      time.Time
	IP        string
	Method    string
	Path      string // クエリを除いたパス
	Query     string
	Status    int
	Bytes     int
	LatencyMS float64 // 応答時間（ミリ秒）
}

// ErrTooLong は行が maxLineLen を超えたときのエラー。
var ErrTooLong = errors.New("accesslog: line too long")

// msPerUnit は応答時間の単位を、ミリ秒に直すための倍率。
◆ 秒からミリ秒への倍率が間違っていて 1.5s が 150ms になっているため
var msPerUnit = map[string]float64{"us": 0.001, "ms": 1, "s": 100}

// parseLatency は "35ms"、"1.5s"、"500us" のような応答時間をミリ秒にする。
func parseLatency(s string) (float64, error) {
	for _, unit := range []string{"us", "ms", "s"} {
		if !strings.HasSuffix(s, unit) {
			continue
		}
		v, err := strconv.ParseFloat(strings.TrimSuffix(s, unit), 64)
		if err != nil || v < 0 {
			return 0, fmt.Errorf("accesslog: bad latency %q", s)
		}
		return v * msPerUnit[unit], nil
	}
	return 0, fmt.Errorf("accesslog: unknown latency unit %q", s)
}

// ParseLine は1行をパースする。形式は次のとおり。
//
//	時刻(RFC3339) IP メソッド パス[?クエリ] ステータス バイト数 応答時間
//
// バイト数が "-" のときは 0 とする。時刻は UTC にそろえる。
func ParseLine(line string) (Entry, error) {
	if len(line) > maxLineLen {
		return Entry{}, ErrTooLong
	}
	f := strings.Fields(line)
	if len(f) != 7 {
		return Entry{}, fmt.Errorf("accesslog: want 7 fields, got %d", len(f))
	}
	t, err := time.Parse(time.RFC3339, f[0])
	if err != nil {
		return Entry{}, fmt.Errorf("accesslog: bad time: %w", err)
	}
	status, err := strconv.Atoi(f[4])
	if err != nil || status < 100 || status > 599 {
		return Entry{}, fmt.Errorf("accesslog: bad status %q", f[4])
	}
	n := 0
	if f[5] != "-" {
		if n, err = strconv.Atoi(f[5]); err != nil || n < 0 {
			return Entry{}, fmt.Errorf("accesslog: bad bytes %q", f[5])
		}
	}
	ms, err := parseLatency(f[6])
	if err != nil {
		return Entry{}, err
	}
	path, query, _ := strings.Cut(f[3], "?")
	return Entry{
		Time: t.UTC(), IP: f[1], Method: f[2], Path: path, Query: query,
		Status: status, Bytes: n, LatencyMS: ms,
	}, nil
}

// ParseAll は複数行をパースする。空行と # で始まる行は読み飛ばし、
// 壊れた行は捨てて bad に数える。
func ParseAll(text string) (entries []Entry, bad int) {
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		e, err := ParseLine(line)
		if err != nil {
			bad++
			continue
		}
		entries = append(entries, e)
	}
	return entries, bad
}

package accesslog

import (
	"math"
	"sort"
	"time"
)

// Summary は複数のエントリをまとめた集計。
type Summary struct {
	Count  int
	Errors int // ステータスが 400 以上の件数
	Bytes  int
	AvgMS  float64
	MaxMS  float64
}

// Summarize はエントリを集計する。
func Summarize(entries []Entry) Summary {
	s := Summary{Count: len(entries)}
	if s.Count == 0 {
		return s
	}
	sum := 0.0
	for _, e := range entries {
		if e.Status >= 400 {
			s.Errors++
		}
		s.Bytes += e.Bytes
		sum += e.LatencyMS
		s.MaxMS = math.Max(s.MaxMS, e.LatencyMS)
	}
	s.AvgMS = sum / float64(s.Count)
	return s
}

// Merge は別々に集計した2つの Summary を1つにまとめる（ログを分割して処理するとき用）。
func Merge(a, b Summary) Summary {
	out := Summary{
		Count:  a.Count + b.Count,
		Errors: a.Errors + b.Errors,
		Bytes:  a.Bytes + b.Bytes,
		MaxMS:  math.Max(a.MaxMS, b.MaxMS),
	}
◆ Merge の平均が件数を無視した単純平均になっているため
	out.AvgMS = (a.AvgMS + b.AvgMS) / 2
	return out
}

// ErrorRate はエラーの割合（パーセント）を返す。件数が 0 なら 0。
func (s Summary) ErrorRate() float64 {
	if s.Count == 0 {
		return 0
	}
	return float64(s.Errors) * 100 / float64(s.Count)
}

// Percentile は応答時間の p パーセンタイル（最近順位法）を返す。
// 空のときは 0。エントリの並びは変えない。
func Percentile(entries []Entry, p float64) float64 {
	if len(entries) == 0 {
		return 0
	}
	ms := make([]float64, len(entries))
	for i, e := range entries {
		ms[i] = e.LatencyMS
	}
	sort.Float64s(ms)
	rank := int(math.Ceil(p / 100 * float64(len(ms))))
	rank = min(max(rank, 1), len(ms))
	return ms[rank-1]
}

// Bucket は1分ぶんのリクエスト数。
type Bucket struct {
	Start time.Time // 分の先頭
	Count int
}

// PerMinute は分ごとのリクエスト数を、時刻の早い順に返す。
func PerMinute(entries []Entry) []Bucket {
	counts := make(map[int]int)
	start := make(map[int]time.Time)
	for _, e := range entries {
		k := e.Time.Minute()
		counts[k]++
		if _, ok := start[k]; !ok {
			start[k] = e.Time.Truncate(time.Minute)
		}
	}
	buckets := make([]Bucket, 0, len(counts))
	for k, n := range counts {
		buckets = append(buckets, Bucket{Start: start[k], Count: n})
	}
	sort.Slice(buckets, func(i, j int) bool { return buckets[i].Start.Before(buckets[j].Start) })
	return buckets
}

// PathCount はパスごとのリクエスト数。
type PathCount struct {
	Path  string
	Count int
}

// TopPaths はリクエストの多いパスを上位 n 件返す。同数ならパスの辞書順。
func TopPaths(entries []Entry, n int) []PathCount {
	counts := make(map[string]int)
	for _, e := range entries {
		counts[e.Path]++
	}
	out := make([]PathCount, 0, len(counts))
	for p, c := range counts {
		out = append(out, PathCount{p, c})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Count != out[j].Count {
			return out[i].Count > out[j].Count
		}
		return out[i].Path < out[j].Path
	})
	if len(out) > n {
		out = out[:n]
	}
	return out
}

